head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > rowNumStatusUniqueId]<br/>RowNum Column 과 RowStatus Column 렌더링 시 각 Cell 의 ID 를 유일값으로 설정합니다.",
    "validation" : [
        "미설정 또는 false 설정 시 RowNum Column 과 RowStatus Column 렌더링 시 각 Cell 의 ID 를 동일한 값으로 설정합니다.",
        "--- RowNum Column 의 ID 는 '_headerRowNumber' 로, RowStatus Column 의 ID 는 '_headerStatusNumber' 로 설정됩니다.",
        "true 설정 시 RowNum Column 과 RowStatus Column 렌더링 시 각 Cell 의 ID 를 유일값으로 설정합니다.",
        "--- 각 Cell 의 ID 에 '_bodyRow_{RowIdx}' 형식의 Suffix 붙여 유일값을 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }    

    // 조건 설정   
    let properties = {               
        rowNumVisible: true,
        rowStatusVisible: true,
        rowNumHeaderValue: "No.",                
        rowStatusHeaderValue: "St.",
        dataList: "data:dlt_bind",     
        rowNumStatusUniqueId: con_rowNumStatusUniqueId.getText(), 
    };

    let cList = $c.gcm.createCList(properties);      
    // let eList = $c.gcm.createEList([""]);

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성   
    $c.gcm.createBasicGridView(cList);

    scwin.btn_rowNumStatusUniqueId_onclick();
}



scwin.btn_rowNumStatusUniqueId_onclick = function (e) {     
    let targetElement = document.querySelector('tr.grid_body_row:not([style*="display: none"])');

    if (targetElement) {
        let tds = Array.from(targetElement.querySelectorAll('td')).slice(0, 2);

        tds.forEach((td, index) => {
                wf_body_bottom.getObj("scwin").setReturnValue(`TD ${index} -> ID: ${td.getAttribute('id')}`);
        });               
    }
}
